import{_ as r,o as a,c as t,a5 as o}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/02-refus-session-ouverte.webp",i="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/03-confirmation.webp",d="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/04-pin-manager.webp",n="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/05-serveur-injoignable.webp",p="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/06-ecran-appairage-vierge.webp",c="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/07-limite-formule.webp",l="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/08-titre-resto-part-egale-avant.webp",u="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/09-titre-resto-part-egale-apres.webp",m="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-01-premiere-synchro.webp",g="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-02-refus-session-ouverte.webp",v="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-03-confirmation.webp",h="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-04-pin-manager.webp",f="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-05-serveur-injoignable.webp",b="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-06-ecran-appairage-vierge.webp",P="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/android-07-limite-formule.webp",q=JSON.parse('{"title":"Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-corrections-appairage.md","filePath":"generated/preuves/2026-11-08-corrections-appairage.md","lastUpdated":null}'),_={name:"preuves/2026-11-08-corrections-appairage.md"};function S(y,e,A,C,T,D){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="corrections-appairage-desappairage-et-apps-lot-hm-partie-2-—-08-11-2026" tabindex="-1">Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026 <a class="header-anchor" href="#corrections-appairage-desappairage-et-apps-lot-hm-partie-2-—-08-11-2026" aria-label="Permalink to &quot;Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-corrections-appairage</code> · 0 image(s) · 0 trace(s)</p><div><p>Défauts relevés par le centre d&#39;aide (<code>docs/DEFAUTS-CENTRE-AIDE.md</code>, « Lot HM ») : désappairage guidé (confirmation + PIN manager), révocation au serveur (place libérée dans la formule), session jamais reprise d&#39;un appairage à l&#39;autre, « Première synchronisation… », écran d&#39;appairage vierge, champs Android synchrones, pavé PIN en tablette paysage, mode formation vérifié avant le PIN, limite de formule / compte suspendu lisibles, texte caméra QR + codes-barres.</p><h2 id="captures-faites-le-08-11-2026-vraie-stack-ios" tabindex="-1">Captures (faites le 08/11/2026, vraie stack iOS) <a class="header-anchor" href="#captures-faites-le-08-11-2026-vraie-stack-ios" aria-label="Permalink to &quot;Captures (faites le 08/11/2026, vraie stack iOS)&quot;">​</a></h2><p>Commerce de démo fictif <code>bistrot.demo+tr1108@vendora.test</code> (« Le Petit Bistrot (démo) », EUR) ; simulateurs dédiés « Agent-a3d7-iPad » (iPad Air 11&quot; M3, caisse principale) et « Agent-a3d7-iPhone » (iPhone 16, téléphone de salle), supprimés ensuite ; gestes par le pilote XCUITest du dépôt (<code>help/tools/mobile/pilote-ios</code>, sans outil MCP). Scénarios d&#39;annotation : <code>help/tools/mobile/scenarios/appareil-caisse-desappairer-ios.json</code> (iPad) et <code>appareil-caisse-desappairer-iphone-ios.json</code> (iPhone) ; mêmes images dans <code>help/public/captures/appareil-caisse/desappairer/</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Appareil</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+s+'" alt=""> <code>02-refus-session-ouverte</code></td><td>iPad</td><td>Refus motivé : « Session de caisse n° 1 ouverte : clôturez-la (rapport Z) avant de désappairer… », aucun PIN demandé.</td></tr><tr><td><img src="'+i+'" alt=""> <code>03-confirmation</code></td><td>iPhone</td><td>« Désappairer cet appareil ? » — ce qui va se passer, <strong>Annuler</strong> / <strong>Continuer</strong>.</td></tr><tr><td><img src="'+d+'" alt=""> <code>04-pin-manager</code></td><td>iPhone</td><td>PIN manager, motif pré-rempli « Désappairage de l&#39;appareil ».</td></tr><tr><td><img src="'+n+'" alt=""> <code>05-serveur-injoignable</code></td><td>iPhone</td><td>Serveur arrêté : <strong>Réessayer</strong> / <strong>Désappairer quand même</strong> / Annuler. Serveur relancé puis <strong>Réessayer</strong> → désappairé, appareil <code>REVOKED</code> au serveur (« Désappairé depuis l&#39;appareil : Désappairage de l&#39;appareil »).</td></tr><tr><td><img src="'+p+'" alt=""> <code>06-ecran-appairage-vierge</code></td><td>iPhone</td><td>Retour sur « Appairer cet appareil », champs vierges (seule l&#39;URL du serveur est gardée).</td></tr><tr><td><img src="'+c+'" alt=""> <code>07-limite-formule</code></td><td>iPhone</td><td>Code créé sous la limite puis consommé formule pleine (appareils factices) : « Limite de la formule Restaurant atteinte : 6 appareils de vente… » au lieu de « Erreur serveur (HTTP_409) ».</td></tr><tr><td><img src="'+l+'" alt=""> <code>08-titre-resto-part-egale-avant</code></td><td>iPhone</td><td>Défaut titre-restaurant reproduit : part égale « Part 1/4 » d&#39;une addition entrecôte + terrine (éligibles) → « Aucun article éligible ».</td></tr><tr><td><img src="'+u+'" alt=""> <code>09-titre-resto-part-egale-apres</code></td><td>iPhone</td><td>Après correction : « Éligible : 7,50 € · plafond : 25,00 € · autorisé : 7,50 € », part encaissée en titre-restaurant.</td></tr></tbody></table><p><strong>Défaut trouvé en faisant ces captures (corrigé, iOS)</strong> : sur iPhone, <strong>Continuer</strong> ne faisait rien — la fermeture de l&#39;alerte de confirmation remettait <code>isPresented</code> à faux, ce qui appelait <code>annuler()</code> juste après <code>confirmer()</code> : l&#39;étape PIN et sa feuille étaient effacées (<code>DesappairageModifier</code>, test <code>testContinuerOuvreLaFeuillePinMalgreLaFermetureDeLAlerte</code>). Android n&#39;est pas concerné (<code>onDismissRequest</code> n&#39;est pas appelé par les boutons d&#39;un <code>AlertDialog</code> Compose).</p><p><strong>Non faites (iOS)</strong> : « Première synchronisation… » sur iOS (l&#39;écran se remplit en moins d&#39;une seconde). Faite sur Android, voir ci-dessous.</p><ul><li>Le serveur de dev du port 8080 (démarré le 07/11, avant <code>POST /api/v1/pos/device/unpair</code>) répondait 404 au désappairage, affiché « Serveur injoignable » : les captures de désappairage complet ont été faites contre un serveur du worktree (port 8088). Redémarrer le serveur de dev pour avoir le comportement à jour.</li></ul><p>Le comportement est couvert par les tests automatiques : <code>DeviceSelfUnpairIntegrationTest</code> (serveur), <code>DeviceUnpairingTest</code> (shared), <code>UnpairViewModelTest</code> et <code>PairingViewModelTest</code> (Android), <code>DesappairageTests</code> (iOS).</p><h2 id="scenario-pour-rejouer-les-captures" tabindex="-1">Scénario pour rejouer les captures <a class="header-anchor" href="#scenario-pour-rejouer-les-captures" aria-label="Permalink to &quot;Scénario pour rejouer les captures&quot;">​</a></h2><ol><li>Serveur du worktree sur un port libre (<code>./gradlew :server:bootRun --args=&#39;--server.port=8086&#39;</code>) contre la base de dev ; commerce de démo fictif : <code>python3 -I help/tools/seed/seed-demo.py --owner-email bistrot.demo+hm@vendora.test --secrets &amp;lt;hors dépôt&gt; --api http://localhost:8086 --no-activity</code> (« Le Petit Bistrot (démo) »).</li><li>Appareils dédiés : <code>help/tools/mobile/appareils.sh creer-ios</code> / <code>creer-android tablette</code> (1600 × 1000, utile aussi pour vérifier le pavé PIN côte à côte).</li><li>Code d&#39;appairage <code>REGISTER</code> (back-office ou <code>POST /api/v1/devices/pairing-codes</code>), appairer avec l&#39;URL du serveur.</li><li>Après la première synchronisation : « Qui êtes-vous ? » → <strong>Désappairer cet appareil</strong> → capture <code>01-confirmation</code> ; <strong>Continuer</strong> → capture <code>02-pin-manager</code> ; PIN de « Sophie (manager) » → écran d&#39;appairage vierge (<code>03-ecran-appairage-vierge</code>), appareil révoqué au back-office (<code>04-fiche-revoquee</code>).</li><li>Limite de formule : abonnement Essentiel (1 appareil) pour le commerce de démo, deux codes créés sous la limite puis le second consommé sur l&#39;appareil → « Limite de la formule Essentiel atteinte : 1 appareil de vente… » (<code>05-limite-formule</code>), au lieu de « Erreur serveur (HTTP_409) — réessayez ».</li><li>Session ouverte : ouvrir une session puis <strong>Désappairer</strong> → refus « Session de caisse n° 1 ouverte : clôturez-la (rapport Z)… » (<code>06-refus-session-ouverte</code>).</li></ol><p>Note : un commerce de démo « Le Petit Bistrot (démo) » (<code>bistrot.demo+hmcorr@vendora.test</code>) a été semé dans la base de dev pendant la préparation ; il est fictif et peut être réutilisé pour ces captures.</p><h2 id="captures-android-tablette-08-11-2026-au-soir" tabindex="-1">Captures Android (tablette, 08/11/2026 au soir) <a class="header-anchor" href="#captures-android-tablette-08-11-2026-au-soir" aria-label="Permalink to &quot;Captures Android (tablette, 08/11/2026 au soir)&quot;">​</a></h2><p>Captures Android faites le 08/11/2026 au soir sur les émulateurs du projet (dérogation accordée pour ce lot) : tablette <code>emulator-5554</code> (AVD « Kds_Tablet », 1600 × 1000) et téléphone <code>emulator-5556</code> (AVD « Medium_Phone_API_36.1 », 1080 × 2400), app de debug <code>pos.android</code> construite depuis <code>main</code> (0d1aecf5), commerce de démo FICTIF « Le Petit Bistrot (démo) » (<code>bistrot.demo+and1108@vendora.test</code>, <code>seed-demo.py --no-activity</code>) sur le serveur de dev <code>localhost:8080</code>. Gestes par <code>help/tools/mobile/drv.py</code> (adb), annotations par <code>annotate.py</code>. La tablette est appairée par un relais TCP local (<code>http://10.0.2.2:18095</code> → <code>localhost:8080</code>) : le relais ralenti de 4 s par connexion pour attraper « Première synchronisation… », puis coupé pour « Serveur injoignable ». Scénarios : <code>help/tools/mobile/scenarios/appareil-caisse-desappairer-android.json</code> et <code>appareil-caisse-appairer-l-appareil-premiere-synchro-android.json</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+m+'" alt=""> <code>android-01-premiere-synchro</code></td><td>Juste après <strong>Appairer</strong> : « Qui êtes-vous ? » affiche « Première synchronisation… les utilisateurs et leurs PIN arrivent du serveur. » (1) et la pastille <strong>Envoi…</strong> (2), sans les bandeaux « &gt; 72 h » ni « aucun utilisateur avec PIN ». Remplace dans l&#39;aide l&#39;ancienne <code>06-android-premiere-synchro</code> (qui montrait l&#39;écran d&#39;appairage, cadres décalés).</td></tr><tr><td><img src="'+g+'" alt=""> <code>android-02-refus-session-ouverte</code></td><td>Session n° 1 ouverte (Camille) → <strong>Menu caisse › Compte › Désappairer cet appareil</strong> : refus motivé (1), <strong>OK</strong> (2), aucun PIN demandé.</td></tr><tr><td><img src="'+v+'" alt=""> <code>android-03-confirmation</code></td><td>Après le Z : « Désappairer cet appareil ? » — ce qui va se passer (1), <strong>Continuer</strong> (2).</td></tr><tr><td><img src="'+h+'" alt=""> <code>android-04-pin-manager</code></td><td>PIN manager (Sophie) saisi (1), motif pré-rempli « Désappairage de l&#39;appareil » (2), <strong>Approuver</strong> (3).</td></tr><tr><td><img src="'+f+'" alt=""> <code>android-05-serveur-injoignable</code></td><td>Relais coupé avant <strong>Approuver</strong> : « Serveur injoignable » — <strong>Réessayer</strong> (1) / <strong>Désappairer quand même</strong> (2) / Annuler. Relais relancé puis <strong>Réessayer</strong> → désappairé, appareil <code>REVOKED</code> au serveur (« Désappairé depuis l&#39;appareil : Désappairage de l&#39;appareil »).</td></tr><tr><td><img src="'+b+'" alt=""> <code>android-06-ecran-appairage-vierge</code></td><td>Retour sur « Appairer cet appareil » (1), champs vierges, URL du serveur gardée.</td></tr><tr><td><img src="'+P+'" alt=""> <code>android-07-limite-formule</code></td><td>Code créé sous la limite, puis formule passée à <strong>Essentiel</strong> (1 appareil, déjà occupé par la caisse virtuelle) par la console : « Limite de la formule Essentiel atteinte : 1 appareil de vente. Passez à une formule supérieure… » (1). Formule remise à Restaurant ensuite.</td></tr></tbody></table><p>Ajoutées au centre d&#39;aide (FR / EN / AR) : <code>desappairer</code> (08, 09, 11, 13) et <code>appairer-l-appareil</code> (06 remplacée).</p><p><strong>Défauts vus en faisant ces captures (non corrigés, à reprendre)</strong> :</p><ul><li><strong>Plan de salle Android : numéros de table coupés</strong> — sur la tablette (caisse et téléphone de salle) comme sur le téléphone, les tables carrées T3, T4, T7, T8 n&#39;affichent que le haut de leur numéro et les rondes T5, T6 sont rognées en bas ; seules T1 et T2 sont lisibles (la coche « Libre » occupe le haut de la vignette). Visible sur <code>docs/captures/2026-11-08-telephone-salle-reglages/android-01-bouton-menu.webp</code> et <code>docs/captures/2026-11-08-libelle-format-appareil/android-02-sur-cette-tablette.webp</code>.</li><li><strong>Caisse Android en mode « Tables »</strong> (tablette, session ouverte) : l&#39;en-tête de la caisse (nom, pastille d&#39;état, bouton <strong>Menu caisse</strong>) n&#39;est pas affiché ; il faut passer en « Vente directe » pour atteindre le menu (désappairer, clôturer…).</li><li><strong>Barre d&#39;état illisible</strong> sur les écrans clairs (appairage, PIN, accueil de la borne, diagnostic du téléphone) : heure et icônes en blanc sur fond clair.</li><li><strong>ANR « POS isn&#39;t responding »</strong> dans la fenêtre « Clôturer la session » quand le champ « Montant compté » reçoit une rafale de touches Retour arrière (<code>adb input keyevent DEL</code> ×5, raison « Waited 5000ms for KeyEvent ») ; la machine était très chargée (charge &gt; 70) — à vérifier sur un appareil réel avant de conclure.</li><li>La demande d&#39;autorisation des <strong>notifications</strong> revient à chaque reconnexion tant qu&#39;elle est refusée (vue deux fois sur chaque appareil).</li><li>En-tête « C Caisse » sur l&#39;écran « Qui êtes-vous ? » du téléphone de salle : sans thème publié, l&#39;app affiche le nom par défaut du thème (<code>ThemeHolder.DEFAULT_NAME</code> = « Caisse ») au lieu du nom de l&#39;appareil (« Téléphone de Lucas ») ou du magasin.</li></ul></div>',3)])])}const E=r(_,[["render",S]]);export{q as __pageData,E as default};
